import{_ as d,o as e,c as a,a5 as i}from"./chunks/framework.CXroN2RO.js";const c=JSON.parse('{"title":"SOLID原則を学ぶ","description":"","frontmatter":{"title":"SOLID原則を学ぶ","study":{"source":"C++ Wiki","status":"published","summary":"SOLIDは、オブジェクト指向設計の経験則5つの頭文字です(Robert C. Martinの整理による)。設計の基礎の概念(責務・結合・依存の方向)を「原則」の形に定式化したものです。","section":"learning","format":"path","domain":"design","collection":"cpp-design","order":2}},"headers":[],"relativePath":"design/solid/index.md","filePath":"design/solid/index.md"}'),s={name:"design/solid/index.md"};function r(n,t,o,l,h,u){return e(),a("div",null,[...t[0]||(t[0]=[i('<div id="第2部-solid原則" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="solid原則を学ぶ" tabindex="-1">SOLID原則を学ぶ <a class="header-anchor" href="#solid原則を学ぶ" aria-label="Permalink to &quot;SOLID原則を学ぶ&quot;">​</a></h1><p>SOLIDは、オブジェクト指向設計の経験則5つの頭文字です(Robert C. Martinの整理による)。<a href="/study/design/foundations/">設計の基礎</a>の概念(責務・結合・依存の方向)を「原則」の形に定式化したものです。</p><table tabindex="0"><thead><tr><th>略</th><th>名前</th><th>一言で</th></tr></thead><tbody><tr><td><a href="/study/design/solid/srp.html">SRP</a></td><td>単一責任の原則</td><td>1つのモジュールの変更理由は1つにする</td></tr><tr><td><a href="/study/design/solid/ocp.html">OCP</a></td><td>開放閉鎖の原則</td><td>追加は新コードで、既存コードの変更なしでできるようにする</td></tr><tr><td><a href="/study/design/solid/lsp.html">LSP</a></td><td>リスコフの置換原則</td><td>派生型は基底型の約束を守り、いつでも置き換え可能にする</td></tr><tr><td><a href="/study/design/solid/isp.html">ISP</a></td><td>インターフェース分離の原則</td><td>使わないものへの依存を強制しない</td></tr><tr><td><a href="/study/design/solid/dip.html">DIP</a></td><td>依存性逆転の原則</td><td>上位方針を下位詳細に依存させず、両方を抽象に依存させる</td></tr></tbody></table><p>仕上げに <a href="/study/design/solid/exercises.html">演習</a> を解いてください。</p><h2 id="この章の前提と読み方" tabindex="-1">この章の前提と読み方 <a class="header-anchor" href="#この章の前提と読み方" aria-label="Permalink to &quot;この章の前提と読み方&quot;">​</a></h2><ul><li>前提知識: <a href="/study/design/foundations/responsibility-and-separation.html">責務</a>、<a href="/study/design/foundations/cohesion-and-coupling.html">凝集度と結合度</a>、<a href="/study/design/foundations/dependency.html">依存の方向</a>、<a href="/study/design/foundations/polymorphism-interface.html">ポリモーフィズム</a>。</li><li><strong>SOLIDは法律ではありません。</strong> どの原則も「変更が来る場所」に適用して初めて元が取れる投資です。各ページの「適用しすぎた場合の弊害」まで読んで1ページ完結です。</li><li>5原則は独立ではなく、SRPで分け、OCP/LSPで拡張可能にし、ISP/DIPで依存を整える、という1セットの道具です。各ページの「原則同士の関係」で繋がりを説明します。</li></ul><hr><p><a href="/study/guide/cpp-index.html">全体目次</a> | 次: <a href="/study/design/solid/srp.html">SRP: 単一責任の原則</a></p>',9)])])}const f=d(s,[["render",r]]);export{c as __pageData,f as default};
